// Adopted is one candidate file together with the unit spans adopted from it.
type Adopted struct {
	Candidate Candidate
	Spans     []Span
}

// BuildRecording turns adopted files into a recording, one record per adoption record ID.
func BuildRecording(items []Adopted) (recording.Recording, error) {
	sorted := make([]Adopted, len(items))
	copy(sorted, items)
	sort.SliceStable(sorted, func(i, j int) bool {
		return sorted[i].Candidate.Path < sorted[j].Candidate.Path
	})
	out := recording.Recording{
		SedumVersion: recording.Version,
		Packages:     map[string]recording.Package{},
	}
	seen := map[string]bool{}
	byRecord := map[string][]Adopted{}
	var order []string
	for _, it := range sorted {
		c := it.Candidate
		if seen[c.Path] {
			return recording.Recording{}, fmt.Errorf("duplicate path %s", c.Path)
		}
		seen[c.Path] = true
		if c.Record == nil {
			return recording.Recording{}, fmt.Errorf("%s: no record", c.Path)
		}
		units := 0
		for _, s := range it.Spans {
			if s.Kind == KindUnit {
				units++
			}
		}
		if units == 0 {
			return recording.Recording{}, fmt.Errorf("%s: no unit spans", c.Path)
		}
		if c.Package != nil {
			out.Packages[c.Package.Name] = recording.Package{
				Extensions: append([]string(nil), c.Package.Extensions...),
			}
		}
		id := c.Record.ID
		if _, ok := byRecord[id]; !ok {
			order = append(order, id)
		}
		byRecord[id] = append(byRecord[id], it)
	}
	for _, id := range order {
		group := byRecord[id]
		first := group[0].Candidate.Record
		rec := recording.Record{RecordID: id, Gen: first.Gen, CreatedAt: first.CreatedAt}
		phase := recording.Phase{Name: recording.DefaultPhase}
		for _, it := range group {
			c := it.Candidate
			file := recording.File{Path: c.Path, Template: c.Template}
			if c.Package != nil {
				file.Package = c.Package.Name
			}
			if c.Captures != nil {
				file.Captures = make(map[string]string, len(c.Captures))
				for k, v := range c.Captures {
					file.Captures[k] = v
				}
			}
			rec.Files = append(rec.Files, file)
			for _, s := range it.Spans {
				if s.Kind != KindUnit {
					continue
				}
				kw := make(map[string]any, len(s.Kwargs))
				for k, v := range s.Kwargs {
					kw[k] = v
				}
				phase.Invocations = append(phase.Invocations, recording.Invocation{Action: s.Action, Kwargs: kw})
			}
		}
		rec.Phases = []recording.Phase{phase}
		out.Records = append(out.Records, rec)
	}
	return out, nil
}

func TestBuildRecordingTwoFiles(t *testing.T) {
	pkg := &genpkg.Package{Name: "py", Extensions: []string{".py"}}
	rec := &record.Record{ID: "imp-1", Gen: "sha256:aa", CreatedAt: "2026-10-16"}
	mk := func(path string) Adopted {
		return Adopted{
			Candidate: Candidate{Path: path, Package: pkg, Template: "t", Record: rec},
			Spans: []Span{
				{Kind: KindHeader, Text: "# header\n"},
				{Kind: KindUnit, Text: "a", Action: "one", Kwargs: map[string]any{"path": path}},
				{Kind: KindUnit, Text: "b", Action: "two", Kwargs: map[string]any{"path": path}},
			},
		}
	}
	got, err := BuildRecording([]Adopted{mk("b.py"), mk("a.py")})
	if err != nil {
		t.Fatal(err)
	}
	if got.SedumVersion != recording.Version {
		t.Errorf("version = %q", got.SedumVersion)
	}
	if !reflect.DeepEqual(got.Packages["py"].Extensions, []string{".py"}) {
		t.Errorf("extensions = %v", got.Packages["py"].Extensions)
	}
	if len(got.Records) != 1 {
		t.Fatalf("records = %d, want 1", len(got.Records))
	}
	r := got.Records[0]
	if r.RecordID != "imp-1" || r.Gen != "sha256:aa" || r.CreatedAt != "2026-10-16" {
		t.Errorf("record = %+v", r)
	}
	if len(r.Files) != 2 || r.Files[0].Path != "a.py" || r.Files[1].Path != "b.py" {
		t.Fatalf("files = %+v", r.Files)
	}
	inv := r.Phases[0].Invocations
	if len(inv) != 4 {
		t.Fatalf("invocations = %d, want 4", len(inv))
	}
	want := []struct{ path, action string }{{"a.py", "one"}, {"a.py", "two"}, {"b.py", "one"}, {"b.py", "two"}}
	for i, w := range want {
		if inv[i].Action != w.action || inv[i].Kwargs["path"] != w.path {
			t.Errorf("invocation %d = %+v", i, inv[i])
		}
	}
}

func TestBuildRecordingTwoRecords(t *testing.T) {
	pkg := &genpkg.Package{Name: "py", Extensions: []string{".py"}}
	unit := []Span{{Kind: KindUnit, Text: "x", Action: "one"}}
	items := []Adopted{
		{Candidate: Candidate{Path: "z.py", Package: pkg, Record: &record.Record{ID: "imp-2"}}, Spans: unit},
		{Candidate: Candidate{Path: "a.py", Package: pkg, Record: &record.Record{ID: "imp-1"}}, Spans: unit},
	}
	got, err := BuildRecording(items)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Records) != 2 || got.Records[0].RecordID != "imp-1" || got.Records[1].RecordID != "imp-2" {
		t.Errorf("records = %+v", got.Records)
	}
}

func TestBuildRecordingErrors(t *testing.T) {
	pkg := &genpkg.Package{Name: "py", Extensions: []string{".py"}}
	rec := &record.Record{ID: "imp-1"}
	unit := Span{Kind: KindUnit, Text: "x", Action: "one"}
	tests := []struct {
		name  string
		items []Adopted
	}{
		{"no unit spans", []Adopted{{Candidate: Candidate{Path: "a.py", Package: pkg, Record: rec}, Spans: []Span{{Kind: KindHeader, Text: "h"}}}}},
		{"duplicate path", []Adopted{
			{Candidate: Candidate{Path: "a.py", Package: pkg, Record: rec}, Spans: []Span{unit}},
			{Candidate: Candidate{Path: "a.py", Package: pkg, Record: rec}, Spans: []Span{unit}},
		}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if _, err := BuildRecording(tt.items); err == nil {
				t.Fatal("want error")
			}
		})
	}
}

func TestBuildRecordingRoundTripsThroughWrite(t *testing.T) {
	pkg := &genpkg.Package{Name: "py", Extensions: []string{".py"}}
	rec := &record.Record{ID: "imp-1", Gen: "sha256:aa", CreatedAt: "2026-10-16"}
	mk := func(path string) Adopted {
		return Adopted{
			Candidate: Candidate{Path: path, Package: pkg, Template: "t", Record: rec},
			Spans: []Span{
				{Kind: KindHeader, Text: "# header\n"},
				{Kind: KindUnit, Text: "a", Action: "one", Kwargs: map[string]any{"path": path}},
				{Kind: KindUnit, Text: "b", Action: "two", Kwargs: map[string]any{"path": path}},
			},
		}
	}
	got, err := BuildRecording([]Adopted{mk("b.py"), mk("a.py")})
	if err != nil {
		t.Fatal(err)
	}
	var buf bytes.Buffer
	if err := recording.Write(&buf, got); err != nil {
		t.Fatal(err)
	}
	back, err := recording.Read(&buf)
	if err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(back, got) {
		t.Errorf("round trip differs:\n got %+v\nwant %+v", back, got)
	}
}

